import functools
import pytest
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
from fastapi.dependencies import DependencyScopeError

def dep_func():
    return "dep"

async def async_dep_func():
    return "async_dep"

class DepClass:
    def __call__(self):
        return "class_dep"

class AsyncDepClass:
    async def __call__(self):
        return "async_class_dep"

app = FastAPI()

@app.get("/")
def read_root(
    dep1 = Depends(functools.partial(dep_func)),
    dep2 = Depends(functools.partial(async_dep_func)),
    dep3 = Depends(functools.partial(DepClass())),
    dep4 = Depends(functools.partial(AsyncDepClass())),
):
    return {"dep1": dep1, "dep2": dep2, "dep3": dep3, "dep4": dep4}

client = TestClient(app)

def test_partial_dependencies():
    response = client.get("/")
    assert response.status_code == 200
    assert response.json() == {"dep1": "dep", "dep2": "async_dep", "dep3": "class_dep", "dep4": "async_class_dep"}

def test_partial_dependency_scope_error():
    def func_dep():
        return "func"

    def gen_dep(f = Depends(func_dep, scope="function")):
        yield "gen"

    app_error = FastAPI()

    @app_error.get("/")
    def root(d = Depends(gen_dep)):
        return d

    with pytest.raises(DependencyScopeError) as excinfo:
        client_error = TestClient(app_error)
        client_error.get("/")

    assert "has a scope of \"request\"" in str(excinfo.value)

def test_partial_dependency_scope_error_with_partial():
    def func_dep():
        return "func"

    def gen_dep(f = Depends(func_dep, scope="function")):
        yield "gen"

    partial_gen_dep = functools.partial(gen_dep)

    app_error = FastAPI()

    @app_error.get("/")
    def root(d = Depends(partial_gen_dep)):
        return d

    # This should raise DependencyScopeError because partial_gen_dep is a generator
    # But with the bug, it won't.
    with pytest.raises(DependencyScopeError) as excinfo:
        client_error = TestClient(app_error)
        client_error.get("/")

    assert "has a scope of \"request\"" in str(excinfo.value)
